func resolveDateWindow(now time.Time, flags dateFlags) (string, string, error) {
	to := strings.TrimSpace(flags.To)
	if to == "" {
		to = now.UTC().Format("2006-01-02")
	}
	from := strings.TrimSpace(flags.From)
	if from == "" {
		start, err := applySince(now.UTC(), strings.TrimSpace(flags.Since))
		if err != nil {
			return "", "", err
		}
		from = start.Format("2006-01-02")
	}
	if _, err := time.Parse("2006-01-02", from); err != nil {
		return "", "", fmt.Errorf("--from must be YYYY-MM-DD: %w", err)
	}
	if _, err := time.Parse("2006-01-02", to); err != nil {
		return "", "", fmt.Errorf("--to must be YYYY-MM-DD: %w", err)
	}
	return from, to, nil
}

func applySince(now time.Time, since string) (time.Time, error) {
	if since == "" {
		since = "365d"
	}
	unit := since[len(since)-1:]
	value, err := strconv.Atoi(strings.TrimSuffix(since, unit))
	if err != nil || value <= 0 {
		return time.Time{}, fmt.Errorf("--since must be a positive duration like 30d, 12m, or 1y")
	}
	switch unit {
	case "d":
		return now.AddDate(0, 0, -value), nil
	case "m":
		return now.AddDate(0, -value, 0), nil
	case "y":
		return now.AddDate(-value, 0, 0), nil
	default:
		return time.Time{}, fmt.Errorf("--since must end with d, m, or y")
	}
}

